from core.rules import RuleMachine


class RefinedSafeSortedDestinationRule:
    """Versión refinada: fija un destino prometedor y prioriza movimientos que mejoran la cota local."""

    name = "safe_sorted_destination_rule"

    def __init__(self, lookahead_bonus=1.0, empty_stack_bonus=0.8, strict_margin=1):
        self.lookahead_bonus = float(lookahead_bonus)
        self.empty_stack_bonus = float(empty_stack_bonus)
        self.strict_margin = int(strict_margin)

    def start(self, partial, memory):
        best_sd = None
        best_key = None

        for sd in range(partial.S):
            if partial.h(sd) >= partial.H:
                continue

            hsd = partial.h(sd)
            gsd = partial.g(sd)
            feasible = 0.0
            promise = 0.0

            if hsd == 0:
                feasible = 1.0
                promise += self.empty_stack_bonus
            else:
                if partial.is_sorted_stack(sd):
                    feasible = 1.0
                    promise += max(0.0, float(partial.H - hsd)) * 0.01
                    if gsd < partial.G:
                        promise += max(0.0, (partial.G - gsd)) * self.lookahead_bonus * 0.01
                else:
                    continue

            key = (-feasible, -promise, hsd, sd)
            if best_key is None or key < best_key:
                best_key = key
                best_sd = sd

        return {"sd": best_sd, "done": best_sd is None}

    def done(self, partial, memory):
        sd = memory.get("sd")
        if sd is None:
            return True
        if partial.h(sd) >= partial.H:
            return True
        if partial.h(sd) == 0:
            return False
        return not partial.is_sorted_stack(sd)

    def allowed(self, partial, memory, candidates):
        sd_fixed = memory.get("sd")
        allowed = []

        def move_score(a):
            so = a.so
            sd = a.sd
            src_top = partial.g(so)
            dst_h = partial.h(sd)
            dst_top = partial.g(sd) if dst_h > 0 else partial.G

            # Preferir completar/estabilizar pilas ordenadas y no vacías,
            # pero sin bloquear vacíos cuando dan mejores continuaciones.
            score = 0.0
            if dst_h == 0:
                score += self.empty_stack_bonus
            elif partial.is_sorted_stack(sd):
                score -= 0.5 * self.lookahead_bonus

            if dst_h > 0 and dst_top >= src_top:
                score -= 1.0
            elif dst_h == 0:
                score -= 0.25

            # Penalizar mover a un destino muy cercano a llenarse si no ayuda mucho.
            score += max(0, dst_h - (partial.H - self.strict_margin)) * 0.2

            # Prefiere sacar de pilas que están claramente mal.
            score -= float(partial.ub(so)) * 0.05
            return score

        for a in candidates:
            if a.so == a.sd:
                continue
            if partial.h(a.so) <= 0:
                continue
            if partial.h(a.sd) >= partial.H:
                continue

            if sd_fixed is not None and a.sd != sd_fixed:
                continue

            src_group = partial.g(a.so)
            dst_h = partial.h(a.sd)
            if src_group < 0:
                continue

            if dst_h == 0:
                allowed.append(a)
                continue

            if not partial.is_sorted_stack(a.sd):
                continue

            if partial.g(a.sd) >= src_group:
                allowed.append(a)

        if not allowed:
            return []

        allowed.sort(key=move_score)
        return allowed


class SafeSortedDestinationRule:
    """Regla base original: permite movimientos hacia una pila no vacía que siga ordenada tras recibir el contenedor."""

    name = "safe_sorted_destination_rule"

    def allowed(self, partial, memory, candidates):
        allowed = []
        for a in candidates:
            so = a.so
            sd = a.sd
            if so == sd:
