            if partial.h(sd) >= partial.H:
                continue

            src_group = partial.g(so)
            if src_group < 0:
                continue

            if partial.h(sd) == 0:
                continue
            if not partial.is_sorted_stack(sd):
                continue
            if partial.g(sd) >= src_group:
                allowed.append(a)

        return allowed


